import { useCartContext } from "@/components/cart-provider";
import { formatCFA } from "@/lib/data";
export default function Checkout(){const {items,subtotal,decrement,add,remove,count}=useCartContext();const delivery=count?1500:0;const total=subtotal+delivery;return <main className="section-shell py-14 md:py-20"><div className="flex items-center gap-2 text-sm text-[#968f86]"><Link href="/menu" className="inline-flex items-center gap-2"><ArrowLeft size={15}/>Menu</Link><span>/</span><span>Checkout</span></div><div className="mt-6 grid gap-6 lg:grid-cols-[1.2fr_.8fr]"><section className="card p-6 md:p-8"><div className="kicker">Your order</div><h1 className="mt-3 font-serif text-4xl">Checkout</h1>{items.length===0?<div className="py-16 text-center"><p className="text-[#a9a39a]">Your cart is empty.</p><Link className="btn btn-gold mt-6" href="/menu">Browse the menu</Link></div>:<div className="mt-8 space-y-4">{items.map(({line,dish})=><div key={dish.id} className="flex items-center gap-4 rounded-2xl border border-white/10 bg-white/[.025] p-4"><div className="min-w-0 flex-1"><div className="font-medium">{dish.name}</div><div className="mt-1 text-sm text-[#8f897f]">{formatCFA(dish.price)}</div></div><div className="flex items-center gap-2 rounded-full bg-white/5 p-1"><button className="grid h-8 w-8 place-items-center rounded-full" onClick={()=>decrement(dish.id)}><Minus size={14}/></button><span className="w-5 text-center text-sm">{line.quantity}</span><button className="grid h-8 w-8 place-items-center rounded-full" onClick={()=>add(dish.id)}><Plus size={14}/></button></div><div className="w-28 text-right font-semibold">{formatCFA(dish.price*line.quantity)}</div><button onClick={()=>remove(dish.id)} className="text-[#777168]"><Trash2 size={16}/></button></div>)}</div>}</section><aside className="card h-fit p-6 md:p-8"><div className="kicker">Order summary</div><div className="mt-6 space-y-3 text-sm"><div className="flex justify-between text-[#aaa39a]"><span>Subtotal</span><span>{formatCFA(subtotal)}</span></div><div className="flex justify-between text-[#aaa39a]"><span>Delivery</span><span>{formatCFA(delivery)}</span></div><div className="my-4 border-t border-white/10"/><div className="flex justify-between text-lg font-semibold"><span>Total</span><span className="text-[#d9a35f]">{formatCFA(total)}</span></div></div>{items.length?<><div className="mt-7 grid gap-3"><input className="field" placeholder="Full name"/><input className="field" placeholder="Phone (+229)"/><textarea className="field min-h-28" placeholder="Delivery address"/><select className="field"><option>FedaPay — Mobile Money / Card</option><option>Pay at table</option></select></div><button className="btn btn-gold mt-6 w-full">Continue to payment</button><p className="mt-3 text-center text-xs leading-5 text-[#726c63]">Frontend demo only. No payment or backend is connected.</p></>:null}</aside></div></main>}
